import{_ as t,o as n,c as a,a4 as s}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0051 — Conservation du texte des échanges avec l'IA : 30 jours par défaut, puis vidé","description":"Extrait de docs/adr/0051-conservation-du-texte-des-echanges-ia.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0051 — Conservation du texte des échanges avec l'IA : 30 jours par défaut, puis vidé","description":"Extrait de docs/adr/0051-conservation-du-texte-des-echanges-ia.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0051-conservation-du-texte-des-echanges-ia.md","filePath":"developpeurs/adr/0051-conservation-du-texte-des-echanges-ia.md"}`),o={name:"developpeurs/adr/0051-conservation-du-texte-des-echanges-ia.md"};function i(r,e,d,u,c,l){return n(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0051--conservation-du-texte-des-échanges-avec-lia--30-jours-par-défaut-puis-vidé" tabindex="-1">ADR-0051 — Conservation du texte des échanges avec l&#39;IA : 30 jours par défaut, puis vidé <a class="header-anchor" href="#adr-0051--conservation-du-texte-des-échanges-avec-lia--30-jours-par-défaut-puis-vidé" aria-label="Permalink to &quot;ADR-0051 — Conservation du texte des échanges avec l&#39;IA : 30 jours par défaut, puis vidé {#adr-0051--conservation-du-texte-des-échanges-avec-lia--30-jours-par-défaut-puis-vidé}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat RGPD-3 (élevé) ; RGPD, art. 5-1-e (limitation de la conservation) ; précise l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0030-conservation-des-donnees-anonymisation">ADR-0030</a> (conservation et anonymisation) pour une catégorie de données qu&#39;elle ne couvrait pas</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Deux colonnes portent du texte d&#39;échange avec un modèle, et aucune n&#39;avait de durée :</p><ul><li><strong><code>ai_conversations.turns</code></strong> contient ce qu&#39;un visiteur écrit à l&#39;assistant public : une question en langue libre, qui peut porter son nom, son adresse ou sa situation. La même colonne sert au dialogue de configuration de site du back-office.</li><li><strong><code>ai_suggestions.payload</code></strong> contient ce qu&#39;un modèle a proposé à partir d&#39;un contenu. Une traduction ou une transcription peut reprendre des données personnelles du contenu source.</li></ul><p>Les conversations passent en <code>expired</code> à leur échéance, mais leur texte n&#39;est jamais effacé. Les suggestions n&#39;ont aucune purge. L&#39;audit (RGPD-3) relève que ces textes sont conservés sans limite et absents de la conservation.</p><p>L&#39;ADR-0030 pose la doctrine « <strong>aucune purge tant que l&#39;organisation n&#39;a pas décidé</strong> », pour tout ce qui porte une valeur administrative ou probatoire : une demande, un journal d&#39;envoi, une preuve de consentement.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><p><strong>Une durée, <code>ai_content_retention_days</code>, dans la politique RGPD de l&#39;organisation.</strong> Elle vaut <strong>30 jours par défaut</strong> et se règle entre 1 jour et 10 ans, depuis l&#39;écran « Politique de rétention » ou par <code>PUT /rgpd/policy</code>.</p></li><li><p><strong>Une exception motivée à la doctrine de l&#39;ADR-0030 : la durée s&#39;applique sans décision.</strong> Ce texte n&#39;a aucune valeur administrative ni probatoire. Ce n&#39;est ni une saisine, ni une preuve, ni un journal : c&#39;est une question écrite par un visiteur anonyme, ou une proposition de modèle. Le garder sans limite faute de décision serait le choix le moins protecteur, pris à la place du DPO. Le choix protecteur est ici l&#39;inverse de celui de l&#39;ADR-0030, et la durée n&#39;accepte donc pas de valeur « non décidé ».</p></li><li><p><strong>À échéance, le texte est vidé et la ligne reste</strong> (<code>app/ai/retention.py:purge_ai_content</code>).</p><ul><li><strong>Conversations</strong> refermées ou échues avant la date limite : <code>turns</code> devient <code>[]</code>, et <code>turn_count</code> survit, c&#39;est une statistique.</li><li><strong>Suggestions créées avant la date limite</strong> : <ul><li>une suggestion <strong>rejetée, remplacée ou expirée</strong> a sa charge utile vidée (<code>{}</code>) ;</li><li>une suggestion <strong>en attente</strong> a aussi sa charge utile vidée, et passe en <code>expired</code> : une proposition vidée ne peut plus être relue ;</li><li>une suggestion <strong>acceptée est conservée</strong>, parce qu&#39;elle est la source de ce qui a été publié (texte alternatif, réponse documentée) et s&#39;applique parfois après coup.</li></ul></li></ul><p>La trace survit : tâche, dates, statut, relecteur, et le journal <code>ai_jobs</code>, qui ne porte jamais de contenu.</p></li><li><p><strong>Exécution par l&#39;ordonnanceur</strong>, dans la tâche quotidienne existante <code>retention_sweep</code>, comme les autres purges de la politique RGPD. Aucune nouvelle tâche n&#39;est ajoutée, et la ligne de journal compte les lignes vidées (<code>conversations_ia_videes</code>, <code>suggestions_ia_videes</code>).</p></li><li><p><strong>La purge vit dans le domaine IA</strong> (<code>app/ai/retention.py</code>), pas dans <code>app/rgpd</code>. Passer une suggestion en <code>expired</code> est une transition de statut, que le paquet RGPD s&#39;interdit de connaître (<code>test_le_paquet_rgpd_ne_sait_pas_changer_un_etat</code>). La durée, elle, reste une décision RGPD, lue dans <code>RgpdPolicy</code>.</p></li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>« Non décidé » par défaut, comme l&#39;ADR-0030</strong></td><td>Laisse le texte des visiteurs indéfiniment, ce qui est exactement le constat de l&#39;audit. La doctrine de l&#39;ADR-0030 protège une archive, alors qu&#39;ici il n&#39;y a rien à protéger.</td></tr><tr><td><strong>Supprimer les lignes</strong></td><td>Ferait disparaître la trace de ce qui a été demandé et décidé, alors que le journal <code>ai_jobs</code> et les relectures (<code>reviewed_by_login</code>) restent utiles au contrôle. Vider suffit à retirer la donnée.</td></tr><tr><td><strong>Vider aussi les suggestions acceptées</strong></td><td>Une réponse documentée acceptée se relit (<code>GET /ai/rag/answers/{id}</code>), et un texte alternatif accepté s&#39;applique à la demande. Les vider casserait ces lectures. Leur texte a la durée du contenu qu&#39;il a produit.</td></tr><tr><td><strong>Une tâche d&#39;ordonnanceur dédiée</strong></td><td>La cadence est la même que celle des autres purges de la politique (quotidienne, par organisation). Une seizième tâche n&#39;apporterait qu&#39;une ligne de journal de plus.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucun texte d&#39;échange avec l&#39;IA ne dépasse la durée de l&#39;organisation, 30 jours si elle n&#39;a rien réglé.</li><li>La purge est bornée par l&#39;organisation, faite de trois <code>UPDATE</code> sans chargement en mémoire, et idempotente.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Une suggestion laissée en attente plus de 30 jours expire.</strong> Un agent qui revient trop tard doit relancer la demande. Une organisation qui relit plus lentement allonge la durée.</li><li><strong>L&#39;export et l&#39;effacement par personne ne couvrent toujours pas ces textes.</strong> Les conversations de l&#39;assistant public sont anonymes (<code>started_by_login</code> nul, aucune adresse IP écrite) : rien ne permet de les rattacher à une personne qui en ferait la demande. La durée courte est la mesure qui tient lieu de droit d&#39;effacement. Le constat de l&#39;audit est donc traité pour la conservation seulement.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Durée dans <code>RgpdPolicy</code>, purge <code>purge_ai_content</code> jouée par <code>retention_sweep</code>, champ dans l&#39;écran « Politique de rétention » — livrés avec cette ADR ; recette <code>apps/api/tests/test_rgpd_retention.py</code> (<code>test_le_texte_des_echanges_ia_est_vide_apres_trente_jours</code>, <code>test_le_balayage_de_conservation_vide_le_texte_des_echanges_ia</code>).</li></ul>',18)])])}const v=t(o,[["render",i]]);export{g as __pageData,v as default};
